n": false, "causal_hypothesis": null, "trait_id": "trunk-fibrous-matting"}, {"observation": "A grey collar hangs against the upper trunk just below the living crown in both seeds and is clearest in render-2. It reads grey or greenish rather than the brown dead fronds of reference-0, and the transition from live fronds is soft.", "evidence_ids": ["render-0", "render-1", "render-2", "reference-0"], "impact": "variation", "uncertain": true, "causal_hypothesis": null, "trait_id": "dead-frond-skirt"}, {"observation": "The trunk is a uniform mid grey-brown, which matches reference-0's distant lower trunk. The stub faces are not lighter or bleached (render-3).", "evidence_ids": ["render-0", "render-1", "render-3", "reference-0", "reference-1"], "impact": "variation", "uncertain": false, "causal_hypothesis": null, "trait_id": "trunk-colour-and-weathering"}, {"observation": "The trunk widens modestly into a flared base at the ground in both seeds.", "evidence_ids": ["render-0", "render-1", "reference-0"], "impact": "supported", "uncertain": false, "causal_hypothesis": null, "trait_id": "basal-flare"}, {"observation": "Fruit clusters are absent. This is a known gap (fn-111) and was not assessed.", "evidence_ids": ["reference-0"], "impact": "optional", "uncertain": false, "causal_hypothesis": null, "trait_id": "fruit-clusters-pendent"}], "coverage": [{"trait_id": "crown-pinnate-arching-fronds", "status": "fail", "evidence_ids": ["render-0", "render-1", "render-2", "reference-0", "reference-1"], "explanation": "The rosette of pinnate fronds is present, but the fronds are straight spokes without arching or drooping, and the crown outline is a starburst, not a hemisphere or shuttlecock."}, {"trait_id": "leaflet-arrangement-stiff-narrow", "status": "pass", "evidence_ids": ["render-0", "render-1", "render-2", "reference-1", "reference-2"], "explanation": "Leaflets are narrow, pointed and set at differing angles, giving a bristly V-section. They are sparse and short, but that falls 